$('apply-preset').addEventListener('click',()=>{const preset=activeProject().presets.find(item=>item.id===$('generation-preset').value);if(!preset)return;record('preset');const s=preset.settings;for(const [id,key] of [['tangent-from','tangentFrom'],['tangent-to','tangentTo'],['tangent-connections','tangentConnections'],['center-from','centerFrom'],['center-to','centerTo'],['center-connections','centerConnections']])$(id).value=s[key];$('tangent-routing').value=s.tangentRouting||'mixed';$('center-routing').value=s.centerRouting||'mixed';$('show-tangents').checked=s.showTangents;$('show-centers').checked=s.showCenters;$('show-outline').checked=s.showOutline;$('show-grid').checked=s.showGrid;$('fill').checked=s.fill;$('seed').value=s.seed;$('amount').value=s.amount;$('amount-value').value=s.amount;$('mode').value=s.mode;$('random-target').value=s.randomTarget||'all';selection=new Set(preset.selection.filter(id=>anchors.some(anchor=>anchor.id===id)));endRecord();render();$('variation-note').textContent=`Applied ${preset.name}.`;});
$('delete-preset').addEventListener('click',()=>{const id=$('generation-preset').value;if(!id)return;activeProject().presets=activeProject().presets.filter(preset=>preset.id!==id);saveProjects();renderPresets();});
function setGroup(kind,value){if(!Number.isFinite(value))return;record(kind);$(`${kind}-value`).value=labelRadius(value);anchors=anchors.map(a=>a.kind===kind&&!a.locked?{...a,radius:value,override:false}:a);establishBase();render();}
for(const kind of ['convex','concave']){$(kind).addEventListener('input',e=>setGroup(kind,Number(e.target.value)));$(kind).addEventListener('change',endRecord);$(`${kind}-value`).addEventListener('change',e=>{const value=Number(e.target.value);if(Number.isFinite(value)){$(kind).value=value;setGroup(kind,value);endRecord();}});}
function setRadius(value,recordId='radius'){if(!Number.isFinite(value)||value<0||value>Number($('radius').max))return;record(recordId);anchors=anchors.map(a=>selection.has(a.id)?{...a,radius:value,override:true}:a);establishBase();render();}
$('radius').addEventListener('input',e=>setRadius(Number(e.target.value)));$('radius').addEventListener('change',endRecord);$('radius-number').addEventListener('change',e=>{if(e.target.value!==''){setRadius(Number(e.target.value),'radius-number');endRecord();}else render();});
for(const side of ['outer','inner'])$(side).addEventListener('click',()=>{record();const winding=windingOf(anchors);anchors=anchors.map(a=>selection.has(a.id)?{...a,side:side==='outer'?winding:-winding}:a);establishBase();endRecord();render();});
$('lock').addEventListener('click',()=>{record();const locked=!selected().every(a=>a.locked);anchors=anchors.map(a=>selection.has(a.id)?{...a,locked}:a);establishBase();endRecord();render();});
for(const [id,key] of [['tangent-participation','tangentParticipation'],['center-participation','centerParticipation']])$(id).addEventListener('change',e=>{if(e.target.value==='')return;record(id);const value=Number(e.target.value);anchors=anchors.map(anchor=>selection.has(anchor.id)?{...anchor,[key]:value}:anchor);endRecord();render();});
function appliesTo(anchor,target){return target==='all'||(target==='selected'&&selection.has(anchor.id))||(target==='convex'&&anchor.kind==='convex')||(target==='concave'&&anchor.kind==='concave');}
function variationFor(seed,reference=anchors){const generated=randomize(base,seed,Number($('amount').value),$('mode').value),target=$('random-target').value;return reference.map((anchor,index)=>appliesTo(anchor,target)?generated[index]:clone(anchor));}
function generate(recordId='variation'){record(recordId);anchors=variationFor($('seed').value);$('amount-value').value=$('amount').value;const target=$('random-target').value;$('variation-note').textContent=`Variation applied to ${target==='all'?'all points':target==='selected'?'the current selection':`${target} points`}.`;render();}
function nextBatchSeed(seed,index){const n=Number(seed);return Number.isSafeInteger(n)?String(n+index):`${seed}-${index+1}`;}
function generateBatch(){const count=Math.max(2,Math.min(12,Math.round(Number($('batch-count').value)||4))),project=activeProject(),reference=clone(anchors),startSeed=$('seed').value;record('batch');for(let index=0;index<count;index++){const seed=nextBatchSeed(startSeed,index);$('seed').value=seed;anchors=variationFor(seed,reference);const defaultName=`BATCH ITERATION ${String(project.iterations.length+1).padStart(2,'0')}`;project.iterations.push({id:`iteration-${Date.now()}-${index}-${Math.random().toString(36).slice(2,7)}`,name:defaultName,state:iterationSnapshot(),thumbnail:$('geometry').innerHTML,createdAt:Date.now()});}$('batch-count').value=String(count);saveProjects();endRecord();render();renderProjects();$('variation-note').textContent=`Generated and saved ${count} iterations. The last is active.`;$('status').textContent=`Saved ${count} batch iterations in ${project.name}.`;}
$('amount').addEventListener('input',()=>generate('amount'));$('amount').addEventListener('change',endRecord);$('amount-value').addEventListener('change',e=>{const value=Number(e.target.value);if(Number.isFinite(value)){$('amount').value=Math.max(0,Math.min(100,value));generate('amount');endRecord();}});$('seed').addEventListener('change',()=>{generate('seed');endRecord();});$('mode').addEventListener('change',()=>{generate('mode');endRecord();});$('random-target').addEventListener('change',()=>{endRecord();render();});$('generate').addEventListener('click',()=>{const n=Number($('seed').value);$('seed').value=String(Number.isSafeInteger(n)?n+1:Math.floor(Math.random()*1000000));generate();endRecord();});$('generate-batch').addEventListener('click',generateBatch);
$('reset')?.addEventListener('click',()=>{record();loadSource(currentSource);endRecord();});$('undo')?.addEventListener('click',undo);$('redo')?.addEventListener('click',redo);
document.querySelectorAll('[data-tool]').forEach(b=>b.addEventListener('click',()=>{tool=b.dataset.tool;render();}));document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{shapeView=b.dataset.view;render();}));
document.querySelectorAll('.mode-tab').forEach(button=>button.addEventListener('click',()=>setDisplayMode(button.dataset.mode)));
for(const id of ['show-grid','fill','show-outline','show-tangents','show-centers'])$(id).addEventListener('change',()=>{record(id);endRecord();render();});for(const id of ['tangent-from','tangent-to','tangent-connections','center-from','center-to','center-connections']){$(id).addEventListener('input',()=>{record(id);render();});$(id).addEventListener('change',endRecord);$(`${id}-value`).addEventListener('change',e=>{const value=Number(e.target.value),control=$(id);if(Number.isFinite(value)){control.value=Math.max(Number(control.min),Math.min(Number(control.max),value));record(id);endRecord();render();}});}for(const id of ['tangent-routing','center-routing'])$(id).addEventListener('change',()=>{record(id);endRecord();render();});for(const [button,control] of [['tangent-next','tangent-connections'],['center-next','center-connections']])$(button).addEventListener('click',()=>{record(control);$(control).value=(Number($(control).value)+1)%1001;endRecord();render();});

function openStart(){ $('start-screen').hidden=false;$('cancel-start').hidden=false;$('cancel-start').textContent=started?'RETURN TO CURRENT FORM':'BEGIN WITH STARTER FORM';$('source-note').classList.remove('warning');$('source-note').textContent='Coordinates are preserved for SVG and DXF export. Large shapes are fitted to the canvas without changing their source dimensions.'; }
function closeStart(){started=true;$('start-screen').hidden=true;}
$('new-source').addEventListener('click',openStart);$('cancel-start').addEventListener('click',closeStart);
$('toggle-controls').addEventListener('click',()=>{const shell=$('app-shell'),hidden=shell.classList.toggle('controls-hidden');$('toggle-controls').textContent=hidden?'CONTROLS +':'CONTROLS −';$('toggle-controls').setAttribute('aria-expanded',String(!hidden));});
$('toggle-projects').addEventListener('click',()=>{const shell=$('app-shell'),hidden=shell.classList.toggle('projects-hidden');$('toggle-projects').textContent=hidden?'BOARDS +':'BOARDS −';$('toggle-projects').setAttribute('aria-expanded',String(!hidden));});
$('new-project').addEventListener('click',()=>{const name=prompt('Board name','UNTITLED BOARD');if(name===null)return;const project=newProject(name.trim().toUpperCase()||'UNTITLED BOARD');projectStore.projects.push(project);projectStore.activeProjectId=project.id;expandedBoards.add(project.id);saveProjects();renderProjects();});
$('rename-project').addEventListener('click',()=>{const project=activeProject(),name=prompt('Board name',project.name);if(name===null)return;project.name=name.trim().toUpperCase()||project.name;saveProjects();renderProjects();});
$('delete-project').addEventListener('click',()=>{const project=activeProject();if(!confirm(`Delete ${project.name} and its saved boards?`))return;projectStore.projects=projectStore.projects.filter(p=>p.id!==project.id);if(!projectStore.projects.length)projectStore.projects.push(newProject('FORM STUDIES'));projectStore.activeProjectId=projectStore.projects[0].id;saveProjects();renderProjects();});
$('project-list').addEventListener('click',e=>{const expand=e.target.closest('[data-board-expand]');if(expand){const id=expand.dataset.boardExpand;if(expandedBoards.has(id))expandedBoards.delete(id);else expandedBoards.add(id);renderProjects();return;}if(e.target.closest('#save-iteration')){saveIteration();return;}if(e.target.closest('#compare-iterations')){renderComparison();$('comparison-screen').hidden=false;return;}if(e.target.closest('#send-overlap')){sendToOverlap();return;}const compare=e.target.closest('[data-compare-id]');if(compare){const id=compare.dataset.compareId;if(comparisonSelection.has(id))comparisonSelection.delete(id);else if(comparisonSelection.size<4)comparisonSelection.add(id);renderProjects();return;}const iteration=e.target.closest('[data-iteration-id]');if(iteration){restoreIteration(iteration.dataset.iterationId);return;}const action=e.target.closest('[data-iteration-action]');if(action){const project=activeProject(),item=project.iterations.find(iteration=>iteration.id===selectedIterationId);if(!item)return;if(action.dataset.iterationAction==='rename'){const name=prompt('Iteration name',item.name);if(name!==null){item.name=name.trim().toUpperCase()||item.name;saveProjects();renderProjects();}}else if(action.dataset.iterationAction==='duplicate'){const copy=clone(item);copy.id=`iteration-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,copy.name=`${item.name} COPY`;copy.createdAt=Date.now();project.iterations.push(copy);selectedIterationId=copy.id;saveProjects();renderProjects();}else if(action.dataset.iterationAction==='delete'&&confirm(`Delete ${item.name}?`)){project.iterations=project.iterations.filter(iteration=>iteration.id!==item.id);selectedIterationId=null;saveProjects();renderProjects();}return;}const board=e.target.closest('[data-project-id]');if(board){projectStore.activeProjectId=board.dataset.projectId;expandedBoards.add(board.dataset.projectId);selectedIterationId=null;comparisonSelection.clear();saveProjects();renderProjects();}});
$('iteration-list').addEventListener('click',e=>{const compare=e.target.closest('[data-compare-id]');if(compare){const id=compare.dataset.compareId;if(comparisonSelection.has(id))comparisonSelection.delete(id);else if(comparisonSelection.size<4)comparisonSelection.add(id);renderProjects();return;}const button=e.target.closest('[data-iteration-id]');if(button)restoreIteration(button.dataset.iterationId);});
$('close-comparison').addEventListener('click',()=>{$('comparison-screen').hidden=true;});
$('comparison-grid').addEventListener('click',e=>{const button=e.target.closest('[data-compare-action]');if(!button)return;const project=activeProject(),item=project.iterations.find(iteration=>iteration.id===button.dataset.iterationId);if(!item)return;if(button.dataset.compareAction==='restore'){restoreIteration(item.id);$('comparison-screen').hidden=true;}else if(button.dataset.compareAction==='duplicate'){const copy=clone(item);copy.id=`iteration-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;copy.name=`${item.name} COPY`;copy.createdAt=Date.now();project.iterations.push(copy);comparisonSelection.add(copy.id);saveProjects();renderProjects();renderComparison();}else if(button.dataset.compareAction==='delete'&&confirm(`Delete ${item.name}?`)){project.iterations=project.iterations.filter(iteration=>iteration.id!==item.id);comparisonSelection.delete(item.id);saveProjects();renderProjects();renderComparison();}});
$('iteration-actions').addEventListener('click',e=>{const action=e.target.dataset.action,project=activeProject(),item=project.iterations.find(iteration=>iteration.id===selectedIterationId);if(!action||!item)return;if(action==='rename'){const name=prompt('Iteration name',item.name);if(name!==null){item.name=name.trim().toUpperCase()||item.name;saveProjects();renderProjects();}}else if(action==='duplicate'){const copy=clone(item);copy.id=`iteration-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;copy.name=`${item.name} COPY`;copy.createdAt=Date.now();project.iterations.push(copy);selectedIterationId=copy.id;saveProjects();renderProjects();}else if(action==='delete'&&confirm(`Delete ${item.name}?`)){project.iterations=project.iterations.filter(iteration=>iteration.id!==item.id);selectedIterationId=null;saveProjects();renderProjects();}});
$('use-sample').addEventListener('click',()=>{record('source');loadSource($('sample').value);endRecord();closeStart();});
$('import-source').addEventListener('click',()=>$('source-file').click());
async function parseDwgFile(file){
 $('source-note').textContent='Loading the DWG decoder…';
 const {LibreDwg,Dwg_File_Type}=await import('./vendor/dist/libredwg-web.js'),decoder=await LibreDwg.create(new URL('./vendor/wasm',import.meta.url).href.replace(/\/$/,'')),data=decoder.dwg_read_data(await file.arrayBuffer(),Dwg_File_Type.DWG);
 if(!data)throw new Error('The DWG decoder could not open this file.');
 try{return parseSvgText(decoder.dwg_to_svg(decoder.convert(data)));}finally{decoder.dwg_free(data);}
}
$('source-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;const ext=file.name.split('.').pop()?.toLowerCase();try{
 let parsed;if(ext==='dxf')parsed=parseDxfText(await file.text());else if(ext==='dwg')parsed=await parseDwgFile(file);else if(ext==='svg')parsed=parseSvgText(await file.text());else throw new Error('Choose an SVG, DXF or DWG file.');
 const points=largestPolygon(parsed.shapes),stem=file.name.replace(/\.(svg|dxf|dwg)$/i,''),key=`import:${Date.now()}`;record('source');sources.set(key,{key,name:stem,points,format:ext,unitsCode:parsed.unitsCode||0});loadSource(key);endRecord();closeStart();$('status').textContent=`Imported ${ext.toUpperCase()} · using ${points.length} anchor points${parsed.shapes.length>1?` from the largest of ${parsed.shapes.length} closed polylines`:''}.`;$('status').classList.remove('warning');
 }catch(error){$('source-note').textContent=error.message;$('source-note').classList.add('warning');}finally{e.target.value='';}});

function exportSettings(){return {tangentFrom:Number($('tangent-from').value),tangentTo:Number($('tangent-to').value),tangentSeed:Number($('tangent-connections').value),tangentRouting:$('tangent-routing').value,centerFrom:Number($('center-from').value),centerTo:Number($('center-to').value),centerSeed:Number($('center-connections').value),centerRouting:$('center-routing').value,showSource:$('export-source').checked,showOutline:$('export-shape').checked,showAnchorMetadata:$('export-anchor-metadata').checked,showTangents:$('export-tangents').checked,showCenters:$('export-centers').checked};}
function download(text,name,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.hidden=true;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCurrent(format){try{const clean=source().name.replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'').toLowerCase()||'tangent',kind=tool==='shape'?'shape':'line-system',units=source().unitsCode||0,settings=exportSettings(),flipY=source().format!=='dxf';if(format==='svg')download(tool==='shape'?shapeSvg(anchors,source().name,settings):lineSystemSvg(anchors,settings,source().name),`${clean}-${kind}.svg`,'image/svg+xml');else download(tool==='shape'?shapeDxf(anchors,units,settings,flipY):lineSystemDxf(anchors,settings,units,flipY),`${clean}-${kind}.dxf`,'application/dxf');$('status').textContent=`${format.toUpperCase()} exported in source coordinates.`;$('status').classList.remove('warning');}catch(error){$('status').textContent=error.message;$('status').classList.add('warning');}}
$('export-svg').addEventListener('click',()=>exportCurrent('svg'));$('export-dxf').addEventListener('click',()=>exportCurrent('dxf'));
for(const id of ['convex','concave','radius','radius-number','tangent-participation','center-participation','amount','seed','mode','random-target','batch-count','show-grid','fill','show-outline','show-tangents','show-centers','tangent-from','tangent-to','tangent-connections','tangent-routing','center-from','center-to','center-connections','center-routing']){const el=$(id);el.addEventListener('pointerdown',()=>record(id));el.addEventListener('keydown',e=>{if(!e.ctrlKey&&!e.metaKey)record(id);});}
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();redo();}});
